using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;

namespace CET6Word {
 public static partial class UITests {
  class FakePronunciation : IPronunciation {public List<string> Calls=new List<string>();public Task<string> SpeakAsync(string text){Calls.Add(text);return Task.FromResult("测试语音");}public void CancelPending(){}public void Dispose(){}}
  static Application app;static DesktopUI ui;static StateStore store;static AppState state;static FakePronunciation audio;static string dir,root;
  static void Check(bool value,string message){if(!value)throw new Exception(message);}
  static IEnumerable<DependencyObject> Descendants(DependencyObject item){for(int i=0;i<VisualTreeHelper.GetChildrenCount(item);i++){var c=VisualTreeHelper.GetChild(item,i);yield return c;foreach(var d in Descendants(c))yield return d;}}
  static IEnumerable<T> Controls<T>() where T:DependencyObject{return Descendants(ui.Window).OfType<T>();}
  static void Pump(){ui.Window.UpdateLayout();var frame=new DispatcherFrame();ui.Window.Dispatcher.BeginInvoke(DispatcherPriority.ContextIdle,new Action(()=>frame.Continue=false));Dispatcher.PushFrame(frame);ui.Window.UpdateLayout();}
  static void Settle(){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(260)};timer.Tick+=(s,e)=>{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);Pump();}
  static void Click(Button b){b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent,b));Pump();}
  static void Click(string content){Click(Controls<Button>().First(b=>b.Content is string && (string)b.Content==content));}
  static void Nav(string name){Click((Button)ui.Window.FindName(name));}
  static Button RowButton(string tag,int index=0){return Controls<Button>().Where(b=>(string)b.Tag==tag).ElementAt(index);}
  static void Menu(string header){var menu=((Button)ui.Window.FindName("MoreNav")).ContextMenu;var item=menu.Items.OfType<MenuItem>().Single(i=>(string)i.Header==header);item.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent,item));Pump();}
  static void Toggle(string content,bool value){var box=Controls<CheckBox>().Single(c=>(string)c.Content==content);box.IsChecked=value;box.RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent,box));Pump();}
  static ListBox StudyList(){return Controls<ListBox>().First();}
  static ScrollViewer StudyScroll(){return Descendants(StudyList()).OfType<ScrollViewer>().First();}
  static string[] VisibleTexts(){return Controls<TextBlock>().Where(t=>t.IsVisible).Select(t=>t.Text).ToArray();}
  static void Capture(string name){Settle();var bitmap=new RenderTargetBitmap((int)Math.Ceiling(ui.Window.ActualWidth),(int)Math.Ceiling(ui.Window.ActualHeight),96,96,PixelFormats.Pbgra32);bitmap.Render(ui.Window);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using(var file=File.Create(Path.Combine(root,name)))png.Save(file);}
  static void Open(){store=new StateStore(dir);state=store.Load(Program.CreateState);ui=new DesktopUI(store,state,audio);ui.Window.Show();Pump();}
  static void OneQuestion(string answer,bool listening=false){Nav("QuizNav");Controls<TextBox>().Single().Text="1";Controls<ComboBox>().Last().SelectedIndex=listening?1:0;Click("开始");Check(Controls<TextBox>().Count()==1,"quiz input missing");Controls<TextBox>().Single().Text=answer;Click("提交");Click("查看结果");}
  public static void Run(Action<string,Action> test,string output) {
   root=output;dir=Path.Combine(output,"ui-integration-"+Guid.NewGuid().ToString("N"));audio=new FakePronunciation();app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};
   test("WPF startup: one column, hidden translations, no automatic playback",()=>{Open();Check(StudyList().Items.Count==20,"list count");Check(Controls<Button>().Where(b=>(string)b.Tag=="expand").All(b=>((WordView)b.DataContext).Level==0),"initial expansion");Check(!VisibleTexts().Any(t=>t==state.Vocabularies[0].Words[0].Meaning),"translation visible initially");Check(audio.Calls.Count==0,"startup auto-played");Capture("ui-default.png");});
   if(ui==null){app.Shutdown();return;}
   string original=state.Vocabularies[0].Words[0].Id;string second=state.Vocabularies[0].Words[1].Id;
   try {
    test("WPF routed row click: progressive expansion and only active learning saved",()=>{var b=RowButton("expand");var row=(WordView)b.DataContext;Click(b);Check(row.Level==1 && VisibleTexts().Contains(row.Meaning),"first click did not expand meaning");Check(!VisibleTexts().Contains(row.ExampleEnglish),"first click exposed example");Click(b);Check(row.Level==2 && VisibleTexts().Contains(row.ExampleEnglish),"second click did not show example");Check(state.Progress[original].LearnCount==2 && state.Progress.Values.Count(p=>p.LearnedAt>0)==1,"active-learning semantics");Nav("BooksNav");Check(StateStore.Decode(File.ReadAllText(store.FilePath)).Progress[original].LearnCount==2,"learning not saved");Nav("StudyNav");Capture("ui-expanded.png");});
    test("WPF global toggle: show meanings without examples or new learning",()=>{int learned=state.Progress.Values.Count(p=>p.LearnedAt>0);Toggle("显示中文",true);Check(Controls<Button>().Where(b=>(string)b.Tag=="expand").All(b=>((WordView)b.DataContext).MeaningVisibility==Visibility.Visible),"global meanings missing");Check(!VisibleTexts().Contains(state.Vocabularies[0].Words[1].Examples[0].English),"global toggle exposed another example");Check(state.Progress.Values.Count(p=>p.LearnedAt>0)==learned && audio.Calls.Count==0,"global toggle counted as learning or played audio");Toggle("显示中文",false);Check(((WordView)RowButton("expand").DataContext).Level==2,"toggle lost expansion state");});
    test("WPF word/example speakers and favorites do not trigger expansion",()=>{var row=(WordView)RowButton("expand").DataContext;Click(RowButton("speak"));Click(RowButton("example"));Check(audio.Calls.SequenceEqual(new[]{row.English,row.ExampleEnglish}),"separate audio sources");Click(RowButton("favorite"));Check(row.Level==2 && state.Notebooks[0].Words.Contains(original),"favorite changed expansion or failed");Check(state.Progress[original].LearnCount==2,"speaker counted as active learning");});
    test("WPF auto reading: user expands word then sentence; page entry stays silent",()=>{Click(RowButton("expand"));Menu("设置与数据");Toggle("主动展开时自动朗读",true);Capture("ui-settings.png");int before=audio.Calls.Count;Nav("StudyNav");Check(audio.Calls.Count==before,"page entry auto-played");Click(RowButton("expand"));Check(audio.Calls.Last()==state.Vocabularies[0].Words[0].English,"word expansion did not read word");Click(RowButton("expand"));Check(audio.Calls.Last()==state.Vocabularies[0].Words[0].Examples[0].English,"example expansion did not read example");before=audio.Calls.Count;Toggle("显示中文",true);Toggle("显示中文",false);Check(audio.Calls.Count==before,"global toggle auto-played");});
    test("WPF mastered row removal, collection page, and manual restoration",()=>{Click(RowButton("master"));Check(state.Progress[original].Mastered && StudyList().Items.Count==20,"master did not remove row");Check(((WordView)StudyList().Items[0]).Word.Id==second,"list did not show next adjacent word");Menu("已掌握词汇");var mastered=Controls<ListBox>().Single();Check(mastered.Items.Count==1,"mastered collection missing");mastered.SelectedIndex=0;Click("恢复所选词");Nav("StudyNav");Check(!state.Progress[original].Mastered && StudyList().Items.Count==20,"restore did not return word");});
    test("WPF scroll only: saved anchor but no new active-learning records",()=>{int learned=state.Progress.Values.Count(p=>p.LearnedAt>0);StudyScroll().ScrollToVerticalOffset(5);Pump();Nav("BooksNav");Check(state.Progress.Values.Count(p=>p.LearnedAt>0)==learned,"scroll counted as learning");Check(state.Positions[state.CurrentVocabulary].FixedAnchor==state.Vocabularies[0].Words[5].Id,"scroll anchor not persisted");Click("收藏词本");var list=Controls<ListBox>().Single();Check(list.Items.Count==1 && ((WordView)list.Items[0]).Word.Id==original,"default favorite not visible in book");Nav("StudyNav");Check((int)StudyScroll().VerticalOffset==5,"page return did not restore anchor");});
    test("WPF random sorting and real window close/reopen restore order and position",()=>{var combos=Controls<ComboBox>().ToList();combos[1].SelectedIndex=1;Pump();var before=StudyList().Items.Cast<WordView>().Select(v=>v.Word.Id).ToArray();Check(!before.SequenceEqual(state.Vocabularies[0].Words.Select(w=>w.Id)),"random sorting remained source order");StudyScroll().ScrollToVerticalOffset(5);Pump();string expected=before[5];int spoken=audio.Calls.Count;ui.Window.Close();Open();Check(state.Positions[state.CurrentVocabulary].Mode=="random","sort mode not restored");Check(StudyList().Items.Cast<WordView>().Select(v=>v.Word.Id).SequenceEqual(before),"random permutation changed on restart");Check((int)StudyScroll().VerticalOffset==5 && state.Positions[state.CurrentVocabulary].RandomAnchor==expected,"restart scroll not restored");Check(audio.Calls.Count==spoken,"restore auto-played");Controls<ComboBox>().ElementAt(1).SelectedIndex=0;Pump();Check(StudyList().Items.Cast<WordView>().Select(v=>v.Word.Id).SequenceEqual(state.Vocabularies[0].Words.Take(20).Select(w=>w.Id)),"fixed order not restored");StudyScroll().ScrollToVerticalOffset(0);Pump();Click(RowButton("expand",1));});
    string quizWord=state.Vocabularies[0].Words.Single(w=>w.Id==second).English;
    test("WPF Chinese quiz: wrong answer feedback, result, separate persisted error",()=>{Nav("QuizNav");Controls<TextBox>().Single().Text="1";Click("开始");Check(!VisibleTexts().Contains(quizWord),"answer exposed before submission");Capture("ui-quiz.png");Controls<TextBox>().Single().Text="deliberately-wrong";Click("提交");Check(VisibleTexts().Any(t=>t.Contains("正确拼写："+quizWord)),"wrong spelling feedback missing");Check(state.Errors[second].Pending && !state.Notebooks[0].Words.Contains(second),"error not separate from favorites");Click("查看结果");Check(VisibleTexts().Any(t=>t.Contains("正确 0") && t.Contains("错误 1")),"result totals missing");Check(Controls<Button>().Any(b=>b.Content as string=="重新默写本轮错词") && Controls<Button>().Any(b=>b.Content as string=="结束"),"optional retry/exit missing");});
    test("WPF retry only wrong words, then two correct rounds remove pending error",()=>{Click("重新默写本轮错词");var q=state.Sessions.Last();Check(q.Words.SequenceEqual(new[]{second}) && !q.Listening,"retry scope or prompt");Controls<TextBox>().Single().Text=quizWord;Click("提交");Click("查看结果");Check(state.Errors[second].Pending && state.Errors[second].Streak==1,"first correct removed too early");Click("结束");OneQuestion(quizWord);Check(!state.Errors[second].Pending && state.Errors[second].Streak==2 && state.Errors[second].WrongCount==1,"second correct threshold/history");Click("结束");});
    test("WPF listening quiz: automatic word audio but no answer leakage",()=>{Nav("QuizNav");Controls<TextBox>().Single().Text="1";Controls<ComboBox>().Last().SelectedIndex=1;int calls=audio.Calls.Count;Click("开始");Check(state.Sessions.Last().Listening,"listening mode not set");Check(audio.Calls.Count==calls+1 && audio.Calls.Last()==quizWord,"listening prompt did not read word");Check(!VisibleTexts().Any(t=>t.IndexOf(quizWord,StringComparison.OrdinalIgnoreCase)>=0),"listening answer leaked in visible UI");Capture("ui-listening.png");Controls<TextBox>().Single().Text=quizWord.ToUpperInvariant();Click("提交");Click("查看结果");Check(state.Sessions.Last().Attempts[0].Correct,"listening did not accept answer");Click("结束");});
    test("WPF error history, threshold editing, and vocabulary manager render",()=>{Menu("错词记录");Check(Controls<ListBox>().Single().Items.Count==0,"graduated error still pending");Controls<ComboBox>().First().SelectedIndex=1;Pump();Check(Controls<ListBox>().Single().Items.Count==1,"history removed with pending status");Menu("设置与数据");Controls<TextBox>().First().Text="3";Click("保存阈值");Check(state.Settings.ErrorThreshold==3,"threshold not saved");Menu("词库管理");Check(Controls<Button>().Any(b=>b.Content as string=="导入 CSV / XLSX"),"import action missing");Check(Controls<ListBox>().Single().Items.Count==1,"built-in library manager missing");});
    test("WPF mastering current word midway preserves next neighbor and scroll",()=>{Nav("StudyNav");StudyScroll().ScrollToVerticalOffset(5);Pump();string removed=((WordView)StudyList().Items[5]).Word.Id;string next=((WordView)StudyList().Items[6]).Word.Id;var button=Controls<Button>().Single(b=>(string)b.Tag=="master" && ((WordView)b.DataContext).Word.Id==removed);Click(button);Check(state.Progress[removed].Mastered,"midway word was not mastered");Check((int)StudyScroll().VerticalOffset==5 && ((WordView)StudyList().Items[5]).Word.Id==next,"mastering midway jumped to top");Check(state.Positions[state.CurrentVocabulary].FixedAnchor==next,"new neighbor anchor overwritten by old row");});
    test("WPF library dropdown keeps independent valid anchors on switch",()=>{var old=state.Vocabularies.Single(v=>v.Id==state.CurrentVocabulary);string anchor=state.Positions[old.Id].FixedAnchor;var imported=VocabularyImport.FromRows(VocabularyImport.ParseCsv("word,meaning\nadapt,适应\nreliable,可靠"),"Imported").Vocabulary;state.Vocabularies.Add(imported);store.Save(state);Nav("StudyNav");Controls<ComboBox>().First().SelectedItem=imported;Pump();Check(state.CurrentVocabulary==imported.Id && StudyList().Items.Count==2,"library switch failed");StateStore.Validate(state);Check(!state.Progress.ContainsKey(imported.Words[0].Id) || state.Progress[imported.Words[0].Id].LearnedAt==0,"cross-library progress shared");Controls<ComboBox>().First().SelectedItem=old;Pump();Check(state.CurrentVocabulary==old.Id && state.Positions[old.Id].FixedAnchor==anchor && (int)StudyScroll().VerticalOffset==5,"old library position not restored");StateStore.Validate(state);});
    test("WPF close flushes complete quiz and settings history to disk",()=>{ui.Window.Close();var loaded=StateStore.Decode(File.ReadAllText(Path.Combine(dir,"state.json")));Check(loaded.Sessions.Count==4 && loaded.Errors[second].WrongCount==1 && loaded.Settings.ErrorThreshold==3,"UI state not durable");Check(loaded.Notebooks[0].Words.SequenceEqual(new[]{original}),"favorites changed by quizzes");});
    V2UITests(test);
   }finally{if(ui.Window.IsVisible)ui.Window.Close();app.Shutdown();}
  }
 }
}
